//! Closed, evidence-backed LAW OPEN DATA source registry.
//!
//! Documentation capture is evidence of request construction, never account scope
//! or successful live delivery. No request endpoint comes from caller input.
use openlegal_domain::legal::Dataset;

pub const GUIDE_INDEX_URL: &str = "https://open.law.go.kr/LSO/openApi/guideList.do";
pub const SERVICE_TERMS_URL: &str = "https://open.law.go.kr/LSO/information/guide.do";
pub const DOCUMENTATION_CHECKED_AT: &str = "2026-10-04";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HistoryMode {
    None,
    StatuteEffective,
    CurrentHistory,
    Unspecified,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DetailMode {
    /// `ID` is the record serial; statutes use `MST` and effective date separately.
    RevisionId,
    /// The guide documents `query=term name`, never an ID request.
    TermName,
    /// No detail guide exists; preserve list bytes without inventing an endpoint.
    ListOnly,
}
#[derive(Clone, Copy, Debug)]
pub struct SourceFamily {
    pub dataset: Dataset,
    pub target: &'static str,
    pub list_path: &'static str,
    pub detail_path: Option<&'static str>,
    pub list_guide: &'static str,
    pub detail_guide: Option<&'static str>,
    pub row_tags: &'static [&'static str],
    pub id_fields: &'static [&'static str],
    pub revision_fields: &'static [&'static str],
    pub title_fields: &'static [&'static str],
    pub body_fields: &'static [&'static str],
    pub list_fields: &'static [&'static str],
    pub detail_fields: &'static [&'static str],
    pub history_mode: HistoryMode,
    pub detail_mode: DetailMode,
    /// Unknown third-party works stay metadata-only until reuse is verified.
    pub metadata_only: bool,
    pub rights_basis: &'static str,
}
impl SourceFamily {
    pub fn guide_url(self) -> String {
        format!(
            "https://open.law.go.kr/LSO/openApi/guideResult.do?htmlName={}",
            self.list_guide
        )
    }
    pub fn detail_parameter(self) -> &'static str {
        match (self.dataset, self.detail_mode) {
            (_, DetailMode::TermName) => "query",
            (Dataset::NationalStatute | Dataset::EnglishStatute, _) => "MST",
            _ => "ID",
        }
    }
}

