#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;
    #[test]
    fn every_dataset_has_one_closed_source_family() {
        assert_eq!(SOURCE_FAMILIES.len(), Dataset::ALL.len());
        let datasets: HashSet<_> = SOURCE_FAMILIES
            .iter()
            .map(|family| family.dataset)
            .collect();
        assert_eq!(datasets.len(), Dataset::ALL.len());
        for dataset in Dataset::ALL {
            let family = source_family(*dataset);
            assert_eq!(family.dataset, *dataset);
            assert!(!family.target.is_empty());
            assert!(
                family
                    .target
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric())
            );
            assert_eq!(family.list_path, "/DRF/lawSearch.do");
            assert!(!family.id_fields.is_empty());
        }
    }
    #[test]
    fn historical_and_unknown_contracts_remain_explicit() {
        assert_eq!(
            source_family(Dataset::SchoolRule).history_mode,
            HistoryMode::CurrentHistory
        );
        assert!(source_family(Dataset::SchoolRule).metadata_only);
        assert_eq!(
            source_family(Dataset::EnglishStatute).history_mode,
            HistoryMode::Unspecified
        );
        assert_eq!(
            source_family(Dataset::LegalTerm).detail_parameter(),
            "query"
        );
        assert_eq!(
            source_family(Dataset::MoefInterpretation).detail_mode,
            DetailMode::ListOnly
        );
        assert!(
            source_family(Dataset::MoefInterpretation)
                .detail_path
                .is_none()
        );
        assert_eq!(
            source_family(Dataset::NtsInterpretation).detail_mode,
            DetailMode::ListOnly
        );
    }
    #[test]
    fn alternate_response_tables_preserve_original_views_and_link_fields() {
        let comparison = GUIDE_ENTRIES
            .iter()
            .find(|entry| entry.guide == "thdCmpInfoGuide")
            .unwrap();
        assert!(comparison.response_fields.contains(&"삼단비교목록상세링크"));
        assert!(comparison.response_fields.contains(&"위임3비교상세링크"));
        let ftc = source_family(Dataset::FtcDecision);
        assert!(ftc.detail_fields.contains(&"의결문"));
        assert!(ftc.body_fields.contains(&"주문"));
        assert!(ftc.body_fields.contains(&"시정권고사항"));
        let ordinance = source_family(Dataset::Ordinance);
        assert!(ordinance.list_fields.contains(&"자치법규ID"));
        assert!(ordinance.list_fields.contains(&"분류seq"));
    }
    #[test]
    fn observed_audit_list_alias_does_not_claim_a_detail_identity_contract() {
        let audit = source_family(Dataset::AuditConsultation);
        assert!(audit.id_fields.contains(&"감사원사전컨설팅일련번호"));
        assert_eq!(audit.revision_fields[0], "감사원사전컨설팅의견서일련번호");
        assert!(!audit.detail_fields.contains(&"감사원사전컨설팅일련번호"));
    }
    #[test]
    fn complete_public_guide_capture_has_no_credentials_or_routes_from_input() {
        let entries: Vec<serde_json::Value> = serde_json::from_str(include_str!(
            "../../../../test-support/fixtures/law-go-kr/catalog-guide-fields.json"
        ))
        .unwrap();
        assert_eq!(GUIDE_ENTRIES.len(), 195);
        assert_eq!(entries.len(), GUIDE_ENTRIES.len());
        let names: HashSet<_> = GUIDE_ENTRIES.iter().map(|entry| entry.guide).collect();
        assert_eq!(names.len(), GUIDE_ENTRIES.len());
        for (entry, captured) in GUIDE_ENTRIES.iter().zip(entries) {
            assert_eq!(entry.guide, captured["guide"]);
            assert_eq!(entry.target, captured["target"]);
            assert_eq!(entry.path, captured["path"]);
            assert!(entry.path.is_empty() || entry.path.starts_with("/DRF/"));
            let fields: Vec<_> = captured["response_fields"]
                .as_array()
                .unwrap()
                .iter()
                .map(|field| field.as_str().unwrap())
                .collect();
            assert_eq!(entry.response_fields, fields, "{}", entry.guide);
        }
        assert_eq!(
            GUIDE_ENTRIES
                .iter()
                .find(|entry| entry.guide == "datDelHstGuide")
                .unwrap()
                .kind,
            GuideKind::NeedsVerification
        );
        assert_eq!(
            GUIDE_ENTRIES
                .iter()
                .find(|entry| entry.guide == "aiSearchGuide")
                .unwrap()
                .kind,
            GuideKind::QueryOnly
        );
    }
}
